midrash=("מעשה שבא מין [כופר] אחד ואמר לרבי עקיבא: 'העולם הזה, מי בראו?' אמר לו: 'הקדוש ברוך הוא'. אמר לו: 'הראני דבר ברור'. אמר לו: 'מה אתה לובש?' אמר לו: 'בגד'. אמר לו: 'מי עשאו?' אמר לו [הכופר]: 'האורג'. אמר לו [רבי עקיבא]: 'איני מאמינך הראני דבר ברור!' אמר לו: 'ומה אראה לך, ואינך יודע שהאורג עשאו?' אמר לו: 'ואתה אינך יודע שהקב\"ה ברא את עולמו?' נפטר אותו המין. אמרו לו תלמידיו [לרבי עקיבא]: 'מה הדבר הברור?' אמר להם: 'בניי, כשם שהבית מודיע על הבנאי, והבגד מודיע על האורג, והדלת על הנגר, כך העולם מודיע על הקב\"ה שהוא בראו'.")

watch=("במכירה גדולה בארצות הברית, הוצע למכירה שעון מיוחד. עלות השעון: 2,000,000 שקל.\n"
"הייתם קונים שעון כזה? חכו לשמוע למה הוא עולה ככה:\n"
"\"לטענת המוכר, מדובר בשעון שכולו נוצר במקרה. להלן התיאור \"כיצד נוצר השעון\":\n"
"תחילת היווצרותו של השעון היתה בשנת 1965. בשנה זו אירעה תאונה במפעל השעונים. כתוצאה מהתאונה עפה במקרה חתיכת מתכת, שבמקרה היתה צורתו כשל גוף שעון, ובמקרה היא התעופפה והתיישבה במקרה על השולחן במעבדה של החברה. בעלי החברה לא שמו לב אל החתיכה שנחה על השולחן הצדדי, ולכן היא נשארה שם...\n"
"באביב 1967, אירעה תאונה אווירית באזור המעבדה. בזמן התאונה התרסק מטוס, ועפה ממנו במקרה חתיכת פלסטיק, שבמקרה היתה לה צורה של עיגול, ובמקרה היא גם התגלגלה דרך הפתח של המעבדה, ובמקרה התיישבה על השולחן. במקרה גם התברר שהיא מתאימה לחלק שיושב שם כבר שנתיים.\n"
"כתוצאה מהתאונה עפו מספר חלקיקים שבמקרה היתה להם צורה של גלגלי שיניים, ובמקרה הם גם התאימו אחד לשני. ובמקרה הם התגלגלו דרך דלת המעבדה ונכנסו לתוכה והסתדרו זה לזה במקרה על השולחן מעצמם בצורה שבמקרה מתאימה לגלגלי שיניים של שעון...\n"
"בשנת 1975 התחוללה סופת הוריקן שהעיפה את כל מה שנקרה בדרכה, וחלק של מתכת בצורה שבמקרה מתאימה להיות מחוגים, עפה במקרה והתיישבה במקרה על השולחן הצדדי שבמפעל.\n"
"בשנת 1980 נשמע פיצוץ עז במפעל. העובדים של המפעל רצו מיד כדי לראות מה קרה, ולמרבה הפלא, התברר שבמקרה, ללא מגע ידי אדם, הסתדרו כל חלקי השעון מעצמם, ועל השולחן היה מונח שעון מורכב בשלמותו... מנהל המעבדה ניגש נרעש אל השעון, קירב אותו לאוזנו, והתברר שבמקרה השעון גם עובד!... ומתקתק!\"")

cold=("ייתכן שהסיפור הזה אינו בדיוק אמיתי, אך יש בו אלמנט לוגי מעניין.\n"
"פרופסור באוניברסיטה הציג שאלה זו לסטודנטים שלו: \" האם כל מה שקיים, נברא ע\"י אלוקים?\". אחד הסטודנטים ענה באומץ: \"כן, נברא ע\"י אלוקים\".\n"
"\"אלוקים ברא הכל?\", שאל הפרופסור.\n"
"\"כן, אדוני\", ענה הסטודנט.\n"
"הפרופסור שאל: \"אם אלוקים ברא הכל, משמעות הדבר שהוא ברא רוע – מאחר והרוע קיים. בהתאם לעקרון שהמעשים שלנו מגדירים אותנו עצמנו, האלוקים הוא רוע\".\n"
"הסטודנט השתתק בשומעו תשובה זו.\n"
"הפרופסור היה מאוד מרוצה מעצמו. הוא התרברב בפני התלמידים שלו שהוכיח שוב שהאמונה באלוקים היא מיתוס.\n"
"סטודנט נוסף הרים את ידו ואמר: \"אני יכול להציג שאלה?\"\n"
"\"כמובן\", ענה הפרופסור.\n"
"הסטודנט קם ושאל: \"האם קיים קור?\"\n"
"\"איזו שאלה? מעולם לא היה לך קר?\". הסטודנטים צחקו על שאלתו של האיש הצעיר.\n"
"האיש הצעיר המשיך: \"למעשה, אדוני, הקור לא קיים. בהתאם לחוקי הפיזיקה, מה שאנו מחשיבים כקור, מהווה למעשה חוסר חום. את האדם או החפץ אפשר ללמוד לפי העובדה האם יש לו או האם הוא מעביר אנרגיה. האפס המוחלט (460 מעלות פרנהייט) הוא היעדר חום מוחלט. כל חומר בטמפרטורה זו הופך להיות לא פעיל ולא מסוגל להגיב. קור לא קיים, אנו יצרנו מילה זו כדי לתאר מה אנו מרגישים בהיעדר חום\".\n"
"הסטודנט המשיך: \"פרופסור, האם קיים חושך?\". הפרופסור ענה: \"כמובן שקיים\".\n"
"הסטודנט ענה: \"אדוני, אתה שוב לא צודק. החושך אינו קיים. החושך הוא למעשה חוסר אור. אנו יכולים לחקור את האור, אך לא את החושך. אנו יכולים להשתמש במנסרה של ניוטון כדי לפרק את האור הלבן להרבה צבעים ולחקור אורכי הגל השונים של כל צבע. אנו לא יכולים למדוד את החושך. קרן אור פשוטה יכולה לחדור לעולם החושך ולהאירו. איך אתה יכול לדעת עד כמה חשוך חלל כלשהו? אתה מודד את כמות האור הקיים. הלא כן? חושך הוא מושג שהאדם משתמש בו כדי לתאר מה קורה בהיעדר אור\".\n"
"בסופו של דבר, האיש הצעיר שאל את הפרופסור: \"אדוני, האם קיים רוע?\"\n"
"הפעם, הפרופסור ענה בחוסר ביטחון: \"כמובן, כפי שכבר אמרתי. אנו רואים אותו כל יום. אכזריות בין האנשים, המון מעשי פשע ואונס בכל העולם. דברים אלה הן שום דבר אחר מאשר דוגמאות של רוע\".\n"
"על זה ענה הסטודנט: \"רוע לא קיים, אדוני, או לפחות הוא אינו קיים בפני עצמו. רוע הוא היעדר אלוקים. הוא דומה לחושך ולקור – מילה שנוצרה ע\"י האדם כדי לתאר את היעדר האלוקים. אלוקים לא יצר רוע. רוע הוא לא אמונה ואהבה, שקיימות כמו האור והחום. רוע הוא התוצאה של היעדר אהבת אלוקים בליבו של האדם. זה כמו הקור שמגיע כאשר אין חום, או כמו החושך, שמגיע כאשר אין אור\".\n"
"הפרופסור השתתק והתיישב.\n"
"שמו של הסטודנט הצעיר היה – אלברט אינשטיין.")

def R_(id,title,age,mn,mx,desc,text,how,tags,src='אנונימי'):
    return dict(id=id,title=title,domain='אמוני',ageLabel=age,ageMin=mn,ageMax=mx,description=desc,text=text,howToUse=how,source=src,tags=tags)
new_r=[
 R_('world-announces-creator','העולם מודיע על בוראו',"כיתה ו'-י\"ב",6,12,'שיחה בין רבי עקיבא לכופר: כמו שהבגד מעיד על האורג, כך העולם מעיד על בוראו.',midrash,'לשאול: איזו ״הוכחה״ זו, ואיפה אנחנו מכירים דבר דרך מה שהוא יצר?',['אמונה','בורא עולם','מדרש'],'מדרש (רבי עקיבא והמין)'),
 R_('watch-by-chance','שעון במקרה',"כיתה ז'-י\"ב",7,12,'שעון שנוצר, לפי המוכר, במקרה: סיפור שמעמיד את המילה ״מקרה״ במבחן.',watch,'לקרוא עד הסוף, ולשאול: מה הסיפור מוכיח, ומה הוא לא מוכיח?',['אמונה','בריאה','סיפור']),
 R_('is-there-cold','האם קיים קור?',"כיתה ט'-י\"ב",9,12,'סטודנט שואל את הפרופסור אם קיים קור, חושך, רוע, ומסיק על אלוקים. בנוסח הזה מצוין שהסיפור לא בהכרח אמיתי.',cold,'מתאים לצוות או לגילאים בוגרים: אפשר לשאול איפה הטיעון חזק ואיפה אפשר להקשות עליו.',['אמונה','רוע','אלוקים','משל']),
]
readings += [r for r in new_r if r['id'] not in rid]

